// Run from the repository root. The catalog is the source of truth.
import {readFileSync, writeFileSync} from 'node:fs';
const catalog = JSON.parse(readFileSync('docs/bridge/questionnaire.v1.json', 'utf8'));
const rules = catalog.questions.map(q => ({id: q.id, options: q.options?.map(o => o.value) ?? [],
  when: q.visibleWhen ?? {}, any: q.visibleWhenAny ?? [], defaults: q.visibleWhenDefaults ?? {}}));
writeFileSync('lib/features/integrations/domain/services/bridge_questionnaire_data.dart',
  '// GENERATED by tools/generate_bridge_questionnaire.mjs; do not edit.\n' +
  `const bridgeQuestionnaireVersion = '${catalog.version}';\n` +
  `const bridgeQuestionnaireJson = r'''${JSON.stringify(rules)}''';\n`);
for (const language of ['ar', 'en']) {
  const path = `assets/translations/${language}.json`;
  const translations = JSON.parse(readFileSync(path, 'utf8'));
  const options = new Map();
  for (const question of catalog.questions) {
    translations.bridge_step.questions[question.id] = question[language];
    for (const option of question.options ?? []) {
      if (options.has(option.value) && options.get(option.value) !== option[language]) {
        throw new Error(`Inconsistent option translation: ${language}/${option.value}`);
      }
      options.set(option.value, option[language]);
      translations.bridge_step.options[option.value] = option[language];
    }
  }
  writeFileSync(path, JSON.stringify(translations, null, 2) + '\n');
}
